import XCTest
@testable import HealthAnalytics

final class BackgroundRefreshConfigTests: XCTestCase {

    /// The app's own constant, so renaming it without updating Info.plist goes red.
    private let patternAnalysisTaskID = HealthAnalyticsApp.patternAnalysisTaskID

    /// Unit tests are hosted in the app, so `Bundle.main` is the built app bundle.
    private var info: [String: Any] { Bundle.main.infoDictionary ?? [:] }

    func test_appRefreshRequestRequiresFetchBackgroundMode() {
        let modes = info["UIBackgroundModes"] as? [String] ?? []
        XCTAssertTrue(modes.contains("fetch"),
                      "BGAppRefreshTaskRequest submit throws without UIBackgroundModes fetch")
    }

    func test_patternAnalysisIdentifierIsPermitted() {
        let permitted = info["BGTaskSchedulerPermittedIdentifiers"] as? [String] ?? []
        XCTAssertTrue(permitted.contains(patternAnalysisTaskID),
                      "BGTaskScheduler rejects identifiers missing from BGTaskSchedulerPermittedIdentifiers")
    }
}
